/* @autogenerated */
package net.civeira.phylax.integrationtest.feature.oauth.flow;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

import io.quarkus.test.junit.QuarkusTest;
import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import io.restassured.response.Response;
import io.restassured.specification.RequestSpecification;
import net.civeira.phylax.integrationtest.feature.oauth.fixtures.OidcTestFixtures;

/**
 * {@code prompt=consent} (task 1.6): the user decides again on every requested scope, even with a
 * stored consent and over a live session; unchecked scopes lose their stored consent and a denial
 * returns {@code access_denied}.
 */
@QuarkusTest
class PromptConsentFlowTest extends OidcIntegrationTestBase {

  private static final String AUTH = "/oauth/openid/" + OidcTestFixtures.TENANT + "/auth";

  private static Map<String, String> query(String prompt) {
    Map<String, String> query = new LinkedHashMap<>();
    query.put("client_id", OidcTestFixtures.CLIENT_ID);
    query.put("redirect_uri", OidcTestFixtures.REDIRECT_URI);
    query.put("response_type", "code");
    query.put("scope", OidcTestFixtures.SCOPE);
    query.put("state", OidcTestFixtures.STATE);
    if (prompt != null) {
      query.put("prompt", prompt);
    }
    return query;
  }

  private static RequestSpecification post(String prompt) {
    return RestAssured.given().redirects().follow(false).contentType(ContentType.URLENC)
        .queryParams(query(prompt));
  }

  private static Response login(String prompt) {
    return post(prompt).formParam("username", OidcTestFixtures.USERNAME)
        .formParam("password", OidcTestFixtures.PASSWORD).formParam("csid", OidcTestFixtures.CSID)
        .post(AUTH);
  }

  @Test
  void withoutPrompt_aStoredConsentIsNotAskedAgain() {
    scopeConsentGateway.whenNoPending();
    Response response = login(null);
    Assertions.assertEquals(302, response.statusCode());
    Assertions.assertNotNull(client.extractAuthCode(response));
  }

  @Test
  void promptConsent_asksAgain_andWithdrawsTheUncheckedScopes() {
    scopeConsentGateway.whenNoPending();

    Response form = login("consent");
    Assertions.assertEquals(200, form.statusCode());
    String body = form.getBody().asString();
    for (String scope : List.of("openid", "profile", "email")) {
      Assertions.assertTrue(body.contains("value=\"" + scope + "\" checked"), scope);
    }
    String preSession = client.extractPreSessionCookie(form);

    Response decided = post("consent").formParam("step", "scope_consent")
        .formParam("csid", OidcTestFixtures.CSID).formParam("scope_accepted", "openid", "profile")
        .cookie("PRE_SESSION_ID", preSession).post(AUTH);

    Assertions.assertEquals(302, decided.statusCode(), decided.getBody().asString());
    Assertions.assertNotNull(client.extractAuthCode(decided));
    Assertions.assertEquals(List.of("openid", "profile"),
        scopeConsentGateway.getLastAcceptedScopes());
    Assertions.assertEquals(List.of("email"), scopeConsentGateway.getLastWithdrawnScopes());
  }

  @Test
  void promptConsent_overALiveSession_showsTheDecision() {
    scopeConsentGateway.whenNoPending();
    String session = client.extractAuthSessionCookie(login(null));
    Assertions.assertNotNull(session);

    Response renewed = RestAssured.given().redirects().follow(false)
        .cookie("AUTH_SESSION_ID", session).queryParams(query("consent")).get(AUTH);

    Assertions.assertEquals(200, renewed.statusCode());
    Assertions
        .assertTrue(renewed.getBody().asString().contains("name=\"step\" value=\"scope_consent\""));
    Assertions.assertNotNull(client.extractPreSessionCookie(renewed));
  }

  @Test
  void promptConsent_denied_isAccessDenied() {
    scopeConsentGateway.whenNoPending();
    String preSession = client.extractPreSessionCookie(login("consent"));

    Response denied = post("consent").formParam("step", "scope_consent_deny")
        .cookie("PRE_SESSION_ID", preSession).post(AUTH);

    Assertions.assertEquals(302, denied.statusCode());
    Assertions.assertTrue(denied.getHeader("Location").contains("error=access_denied"));
    Assertions.assertEquals(0, scopeConsentGateway.getAcceptedCount());
  }

  @Test
  void promptNone_withAnotherValue_isInvalidRequest() {
    Response response =
        RestAssured.given().redirects().follow(false).queryParams(query("none consent")).get(AUTH);
    Assertions.assertEquals(302, response.statusCode());
    Assertions.assertTrue(response.getHeader("Location").contains("error=invalid_request"));
  }
}
